    final RenderFixture fixture = new RenderFixture();
    fixture.view.setDefaultCharset(StandardCharsets.UTF_16);

    fixture.view.render(Collections.emptyMap(), TEXT_HTML_UTF8, fixture.exchange).block();

    assertEquals(StandardCharsets.UTF_8, fixture.engine.lastInvocation().charset);
