@Test
void renderSetsTheContentLanguageHeaderToTheViewLocale() {

    final RenderFixture fixture = new RenderFixture();
    fixture.view.setLocale(Locale.GERMANY);

    fixture.view.render(Collections.emptyMap(), TEXT_HTML_UTF8, fixture.exchange).block();

    assertEquals(Locale.GERMANY, fixture.exchange.response.getHeaders().getContentLanguage());
