@Test
void renderMergesStaticVariablesPathVariablesAndModelAttributesWithModelPrecedence() {

    final RenderFixture fixture = new RenderFixture();
    fixture.view.addStaticVariable("staticOnly", "static");
    fixture.view.addStaticVariable("shared", "from-static");

    final Map<String, Object> pathVars = new HashMap<>();
    pathVars.put("pathOnly", "path");
    pathVars.put("shared", "from-path");
    fixture.exchange.getAttributes().put(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE, pathVars);

    final Map<String, Object> model = new LinkedHashMap<>();
    model.put("modelOnly", "model");
    model.put("shared", "from-model");

    fixture.view.render(model, TEXT_HTML_UTF8, fixture.exchange).block();

    final IContext context = fixture.engine.lastInvocation().context;
    assertEquals("static", context.getVariable("staticOnly"));
    assertEquals("path", context.getVariable("pathOnly"));
    assertEquals("model", context.getVariable("modelOnly"));
    assertEquals("from-model", context.getVariable("shared"));
}


