}


@Test
void renderExposesSpringRequestContextAndEvaluationContextAsVariables() {

    final RenderFixture fixture = new RenderFixture();
    final Map<String, Object> model = new LinkedHashMap<>();
    model.put("name", "World");

    fixture.view.render(model, TEXT_HTML_UTF8, fixture.exchange).block();

    final IContext context = fixture.engine.lastInvocation().context;

    final Object springRequestContext =
            context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT);
    assertTrue(springRequestContext instanceof RequestContext);
    assertEquals("World", ((RequestContext) springRequestContext).getModel().get("name"));

    final Object thymeleafRequestContext =
            context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT);
    assertTrue(thymeleafRequestContext instanceof SpringWebFluxThymeleafRequestContext);
    assertSame(fixture.exchange,
            ((SpringWebFluxThymeleafRequestContext) thymeleafRequestContext).getServerWebExchange());

    final Object evaluationContext = context.getVariable(
            ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME);
    assertTrue(evaluationContext instanceof ThymeleafEvaluationContext);
    assertSame(fixture.applicationContext,
            ((ThymeleafEvaluationContext) evaluationContext).getApplicationContext());
}


@Test
void renderUsesTheWebFluxConversionServiceBeanWhenAvailable() {

    final SentinelConversionService conversionService = new SentinelConversionService();
    final GenericApplicationContext applicationContext = new GenericApplicationContext();
    applicationContext.registerBean("webFluxConversionService", ConversionService.class, () -> conversionService);
    applicationContext.refresh();

    final RenderFixture fixture = new RenderFixture(applicationContext);

    fixture.view.render(Collections.emptyMap(), TEXT_HTML_UTF8, fixture.exchange).block();

    final ThymeleafEvaluationContext evaluationContext = (ThymeleafEvaluationContext)
            fixture.engine.lastInvocation().context.getVariable(
                    ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME);

    final Object converted = evaluationContext.getTypeConverter().convertValue(
            "value", TypeDescriptor.valueOf(String.class), TypeDescriptor.valueOf(Object.class));

    assertEquals("converted[value]", converted);
    assertTrue(conversionService.conversions > 0);
}


@Test
void renderDoesNotUseAnySpecialConversionServiceWhenTheBeanIsAbsent() {

    final RenderFixture fixture = new RenderFixture();

    fixture.view.render(Collections.emptyMap(), TEXT_HTML_UTF8, fixture.exchange).block();

    final ThymeleafEvaluationContext evaluationContext = (ThymeleafEvaluationContext)
            fixture.engine.lastInvocation().context.getVariable(
                    ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME);

