    @Test
    @DisplayName("Element and attribute definitions are injected into aware processors")
    public void definitionsAreInjectedIntoAwareProcessors() {

        final DefinitionsAwareElementTagProcessor elementProcessor =
                new DefinitionsAwareElementTagProcessor(TemplateMode.HTML, "dd", 100);
        final DefinitionsAwarePreProcessor preProcessor =
                new DefinitionsAwarePreProcessor(TemplateMode.HTML, 100);
        final DefinitionsAwarePostProcessor postProcessor =
                new DefinitionsAwarePostProcessor(TemplateMode.HTML, 100);

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(processorDialect("defs-processors", "dd", 100, elementProcessor)),
                new DialectConfiguration(new TestPreProcessorDialect("defs-pre", preProcessors(preProcessor))),
                new DialectConfiguration(new TestPostProcessorDialect("defs-post", postProcessors(postProcessor)))));

        assertNotNull(configuration.getElementDefinitions());
        assertNotNull(configuration.getAttributeDefinitions());

        assertSame(configuration.getElementDefinitions(), elementProcessor.getElementDefinitions());
        assertSame(configuration.getAttributeDefinitions(), elementProcessor.getAttributeDefinitions());

        assertSame(configuration.getElementDefinitions(), preProcessor.getElementDefinitions());
        assertSame(configuration.getAttributeDefinitions(), preProcessor.getAttributeDefinitions());

        assertSame(configuration.getElementDefinitions(), postProcessor.getElementDefinitions());
        assertSame(configuration.getAttributeDefinitions(), postProcessor.getAttributeDefinitions());
    }



