        private HttpStatusCode statusCode = HttpStatusCode.valueOf(200);
        private boolean committed = false;
        private int writeWithCount = 0;
        private int writeAndFlushWithCount = 0;
        private byte[] body;


        @Override
        public boolean setStatusCode(final HttpStatusCode statusCode) {
            this.statusCode = statusCode;
