        }


        @Override
        public boolean isCommitted() {
            return this.committed;
        }


        @Override
        public Mono<Void> writeWith(final Publisher<? extends DataBuffer> body) {
            this.writeWithCount++;
            this.body = join(body);
            this.committed = true;
            return Mono.empty();
        }


        @Override
        public Mono<Void> writeAndFlushWith(
                final Publisher<? extends Publisher<? extends DataBuffer>> body) {
            this.writeAndFlushWithCount++;
            this.body = join(Flux.from(body).concatMap(inner -> Flux.from(inner)));
            this.committed = true;
            return Mono.empty();
        }


        @Override
        public Mono<Void> setComplete() {
            this.committed = true;
            return Mono.empty();
        }


        private static byte[] join(final Publisher<? extends DataBuffer> body) {
            final DataBuffer joined = DataBufferUtils.join(body).block();
            if (joined == null) {
                return new byte[0];
            }
            try {
                final byte[] bytes = new byte[joined.readableByteCount()];
                joined.read(bytes);
                return bytes;
            } finally {
                DataBufferUtils.release(joined);
            }
        }


        byte[] getBody() {
            return this.body == null ? new byte[0] : this.body.clone();
        }


        String getBodyAsString() {
            return new String(getBody(), StandardCharsets.UTF_8);
        }


        int getWriteWithCount() {
            return this.writeWithCount;
        }


        int getWriteAndFlushWithCount() {
