    @Test
    void renderUsesFlushWritesForDataDrivenExecution() {

        final SpringWebFluxTemplateEngine engine = newEngine();
        final ThymeleafReactiveView view = configuredView(engine,
                "<ul><li th:each=\"item : ${items}\" th:text=\"${item}\">item</li></ul>");

        final TestServerWebExchange exchange = new TestServerWebExchange();
        view.render(Map.of("items", new ReactiveDataDriverContextVariable(Flux.just("a", "b", "c"), 2)),
                MediaType.TEXT_HTML, exchange).block();

