    @Test
    void renderAddsPublisherSupplierAndFunctionReactiveModelAdditionsToTheModel() {

        final Supplier<Publisher<?>> supplier = () -> Mono.just("supplier");
        final Function<ServerWebExchange, Publisher<?>> function =
                exchange -> Mono.just(exchange.getRequest().getURI().getPath());

        final Map<String, Object> additions = new LinkedHashMap<>();
        additions.put(SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("fromPublisher"),
                Flux.just("publisher"));
        additions.put(SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("fromSupplier"), supplier);
        additions.put(SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("fromFunction"), function);
        additions.put(SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("nullValue"), null);
        additions.put(SpringReactiveModelAdditionsUtils.toReactiveModelAdditionName("notReactive"), new Object());

        final SpringWebFluxTemplateEngine engine = newEngine(additions);
        final ThymeleafReactiveView view = configuredView(engine,
                "<p th:text=\"${fromPublisher + '|' + fromSupplier + '|' + fromFunction + '|' + " +
                "#vars.containsKey('nullValue') + '|' + #vars.containsKey('notReactive')}\">fallback</p>");

        final TestServerWebExchange exchange = new TestServerWebExchange();
