    static void run(final String name, final TemplateMode mode, final String markup, final IProcessor[] procs) throws Exception {
        final TemplateEngine engine = new TemplateEngine();
        final StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode(mode);
        engine.setTemplateResolver(resolver);
        engine.setDialect(new Dialect(new LinkedHashSet<IProcessor>(Arrays.asList(procs))));

        final IEngineConfiguration configuration = engine.getConfiguration();
        final TemplateData templateData = new TemplateData("test", null, new StringTemplateResource("x"), mode, null);
        final EngineContext ctx = new EngineContext(configuration, templateData, null, Locale.US, new HashMap<String,Object>());

        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();
        handler.setContext(ctx);
        final Rec next = new Rec();
        handler.setNext(next);

        final IModel model = ctx.getModelFactory().parse(templateData, markup);
        ((TemplateModel)model).process(handler);

        System.out.println("### " + name + " => [" + next.output() + "]");
        System.out.println("    events: " + next.events);
    }

    public static final class Dialect implements IProcessorDialect {
        private final Set<IProcessor> p;
        public Dialect(final Set<IProcessor> p) { this.p = p; }
        public String getPrefix() { return "t"; }
        public int getDialectProcessorPrecedence() { return 0; }
        public Set<IProcessor> getProcessors(String prefix) { return this.p; }
        public String getName() { return "Test"; }
    }

    public static final class Rec extends AbstractTemplateHandler {
        final List<String> events = new ArrayList<String>();
        private final StringBuilder sb = new StringBuilder();
        private void rec(final String prefix, final ITemplateEvent e) {
            events.add(prefix + ":" + e.toString());
            try { final Writer w = new StringWriter(); e.write(w); sb.append(w.toString()); }
            catch (final Exception ex) { throw new RuntimeException(ex); }
        }
        public String output() { return sb.toString(); }
        @Override public void handleTemplateStart(ITemplateStart e) { rec("start", e); }
        @Override public void handleTemplateEnd(ITemplateEnd e) { rec("end", e); }
        @Override public void handleXMLDeclaration(IXMLDeclaration e) { rec("xmldecl", e); }
        @Override public void handleDocType(IDocType e) { rec("doctype", e); }
        @Override public void handleCDATASection(ICDATASection e) { rec("cdata", e); }
        @Override public void handleComment(IComment e) { rec("comment", e); }
        @Override public void handleText(IText e) { rec("text", e); }
        @Override public void handleStandaloneElement(IStandaloneElementTag e) { rec("standalone", e); }
        @Override public void handleOpenElement(IOpenElementTag e) { rec("open", e); }
        @Override public void handleCloseElement(ICloseElementTag e) { rec("close", e); }
        @Override public void handleProcessingInstruction(IProcessingInstruction e) { rec("pi", e); }
    }
}
