package org.thymeleaf.engine;

import java.util.*;

import org.thymeleaf.IEngineConfiguration;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.EngineContext;
import org.thymeleaf.context.ITemplateContext;
import org.thymeleaf.model.*;
import org.thymeleaf.processor.IProcessor;
import org.thymeleaf.processor.element.*;
import org.thymeleaf.templatemode.TemplateMode;
import org.thymeleaf.templateresolver.StringTemplateResolver;
import org.thymeleaf.templateresource.StringTemplateResource;

public class Proto4 {

    public static void main(final String[] args) throws Exception {
        run("elementModel modify+removeAttr", TemplateMode.HTML, "<div t:up=\"1\">hello</div>", new IProcessor[] {
                new AbstractElementModelProcessor(TemplateMode.HTML, "t", null, false, "up", true, 100) {
                    protected void doProcess(ITemplateContext c, IModel model, IElementModelStructureHandler sh) {
                        final IModelFactory f = c.getModelFactory();
                        final IOpenElementTag tag = (IOpenElementTag) model.get(0);
                        final Map<String,String> attrs = new LinkedHashMap<String,String>(tag.getAttributeMap());
                        attrs.remove("t:up");
                        model.replace(0, f.createOpenElementTag(tag.getElementCompleteName(), attrs, AttributeValueQuotes.DOUBLE, false));
                        for (int i = 1; i < model.size(); i++) {
                            if (model.get(i) instanceof IText) {
                                final IText t = (IText) model.get(i);
                                model.replace(i, f.createText(t.getText().toUpperCase()));
                            }
                        }
                    }
                }
        });
        run("boundaries simple", TemplateMode.HTML, "<p>x</p>", new IProcessor[] {
                new org.thymeleaf.processor.templateboundaries.AbstractTemplateBoundariesProcessor(TemplateMode.HTML, 100) {
                    public void doProcessTemplateStart(ITemplateContext c, ITemplateStart e, org.thymeleaf.processor.templateboundaries.ITemplateBoundariesStructureHandler sh) { sh.insert("S", false); }
                    public void doProcessTemplateEnd(ITemplateContext c, ITemplateEnd e, org.thymeleaf.processor.templateboundaries.ITemplateBoundariesStructureHandler sh) { sh.insert("E", false); }
                }
        });
        run("insertBefore only", TemplateMode.HTML, "<div t:a=\"1\">body</div>", new IProcessor[] {
                new AbstractElementTagProcessor(TemplateMode.HTML, "t", null, false, "a", true, 100) {
                    protected void doProcess(ITemplateContext c, IProcessableElementTag tag, IElementTagStructureHandler sh) {
                        final IModelFactory f = c.getModelFactory();
                        sh.insertBefore(f.createModel(f.createText("BEFORE")));
                    }
                }
        });
        run("open setBodyText processable + text processor", TemplateMode.HTML, "<div t:a=\"1\">body</div>", new IProcessor[] {
                new AbstractElementTagProcessor(TemplateMode.HTML, "t", null, false, "a", true, 100) {
                    protected void doProcess(ITemplateContext c, IProcessableElementTag tag, IElementTagStructureHandler sh) {
                        sh.setBody("BODY", true);
                    }
                },
                new org.thymeleaf.processor.text.AbstractTextProcessor(TemplateMode.HTML, 100) {
                    protected void doProcess(ITemplateContext c, IText t, org.thymeleaf.processor.text.ITextStructureHandler sh) {
                        sh.setText("[" + t.getText() + "]");
                    }
                }
        });
        run("open setBodyText not processable", TemplateMode.HTML, "<div t:a=\"1\">body</div>", new IProcessor[] {
                new AbstractElementTagProcessor(TemplateMode.HTML, "t", null, false, "a", true, 100) {
                    protected void doProcess(ITemplateContext c, IProcessableElementTag tag, IElementTagStructureHandler sh) {
                        sh.setBody("BODY", false);
                    }
                },
                new org.thymeleaf.processor.text.AbstractTextProcessor(TemplateMode.HTML, 100) {
                    protected void doProcess(ITemplateContext c, IText t, org.thymeleaf.processor.text.ITextStructureHandler sh) {
                        sh.setText("[" + t.getText() + "]");
                    }
                }
        });
        run("replaceWith model processable", TemplateMode.HTML, "<div t:a=\"1\">body</div>", new IProcessor[] {
                new AbstractElementTagProcessor(TemplateMode.HTML, "t", null, false, "a", true, 100) {
                    protected void doProcess(ITemplateContext c, IProcessableElementTag tag, IElementTagStructureHandler sh) {
                        final IModelFactory f = c.getModelFactory();
                        sh.replaceWith(f.createModel(f.createText("R")), true);
                    }
                },
                new org.thymeleaf.processor.text.AbstractTextProcessor(TemplateMode.HTML, 100) {
                    protected void doProcess(ITemplateContext c, IText t, org.thymeleaf.processor.text.ITextStructureHandler sh) {
                        sh.setText("[" + t.getText() + "]");
                    }
                }
        });
        run("local var", TemplateMode.HTML, "<div t:set=\"1\"><span t:show=\"1\">?</span></div>", new IProcessor[] {
                new AbstractElementTagProcessor(TemplateMode.HTML, "t", null, false, "set", true, 100) {
                    protected void doProcess(ITemplateContext c, IProcessableElementTag tag, IElementTagStructureHandler sh) {
                        sh.setLocalVariable("v", "VALUE");
                    }
                },
                new AbstractElementTagProcessor(TemplateMode.HTML, "t", null, false, "show", true, 100) {
                    protected void doProcess(ITemplateContext c, IProcessableElementTag tag, IElementTagStructureHandler sh) {
                        sh.setBody(String.valueOf(c.getVariable("v")), false);
                    }
                }
        });
        run("element name match", TemplateMode.HTML, "<p>x</p><div>y</div>", new IProcessor[] {
                new AbstractElementTagProcessor(TemplateMode.HTML, "t", "p", false, null, false, 100) {
                    protected void doProcess(ITemplateContext c, IProcessableElementTag tag, IElementTagStructureHandler sh) {
                        sh.setAttribute("data-p", "yes");
                    }
                }
        });
    }

    static void run(final String name, final TemplateMode mode, final String markup, final IProcessor[] procs) throws Exception {
        final TemplateEngine engine = new TemplateEngine();
        final StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode(mode);
        engine.setTemplateResolver(resolver);
        engine.setDialect(new Proto3.Dialect(new LinkedHashSet<IProcessor>(Arrays.asList(procs))));

        final IEngineConfiguration configuration = engine.getConfiguration();
        final TemplateData templateData = new TemplateData("test", null, new StringTemplateResource("x"), mode, null);
        final EngineContext ctx = new EngineContext(configuration, templateData, null, Locale.US, new HashMap<String,Object>());

        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();
        handler.setContext(ctx);
        final Proto3.Rec next = new Proto3.Rec();
        handler.setNext(next);

        try {
            final IModel model = ctx.getModelFactory().parse(templateData, markup);
            ((TemplateModel)model).process(handler);
        } catch (final Throwable t) {
            System.out.println("### " + name + " => EXCEPTION " + t.getClass().getName() + ": " + t.getMessage());
            return;
        }
        System.out.println("### " + name + " => [" + next.output() + "]  level=" + ctx.level());
    }
}
