        assertEquals("Context cannot be null", exception.getMessage());

    }


    @Test
    public void setContextRejectsContextWithoutTemplateMode() {

        final Harness harness = new Harness(HTML, Collections.<IProcessor>emptyList());
        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();

        final ITemplateContext contextWithoutTemplateMode =
                (ITemplateContext) Proxy.newProxyInstance(
                        ProcessorTemplateHandlerTests.class.getClassLoader(),
                        new Class<?>[]{ITemplateContext.class},
                        new InvocationHandler() {
                            public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
                                if ("getTemplateMode".equals(method.getName())) {
                                    return null;
                                }
                                return invokeDelegate(harness.context, method, args);
                            }
                        });

        final IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> handler.setContext(contextWithoutTemplateMode));

        assertEquals("Template Mode returned by context cannot be null", exception.getMessage());

    }


    @Test
