        harness.handler.handleTemplateStart(TemplateStart.TEMPLATE_START_INSTANCE);
        // An open element that is never closed: model level will stay at 1 at template end
        harness.handler.handleOpenElement(modelFactory.createOpenElementTag("div"));

        // No exception is raised: the handler "fails fast" on template end because there are no
        // template boundaries processors, and therefore no tear down checks are performed.
        harness.handler.handleTemplateEnd(TemplateEnd.TEMPLATE_END_INSTANCE);

        assertEquals(3, harness.next.events.size());
        assertTrue(harness.next.events.get(1) instanceof IOpenElementTag);
        assertTrue(harness.next.events.get(2) instanceof ITemplateEnd);

    }


