/**
 * Tests for {@link ProcessorTemplateHandler}.
 *
 * <p>
 *   The handler is exercised by feeding it real (parsed) template events through a real engine
 *   configuration/context, but without the pre-/post-processing chain of the engine, so that the
 *   events arriving at the handler and the events it produces (recorded by a "next" handler) can be
 *   asserted directly.
 * </p>
 */
public class ProcessorTemplateHandlerTests {

    private static final TemplateMode HTML = TemplateMode.HTML;
    private static final TemplateMode XML = TemplateMode.XML;

    private static final String DIALECT_PREFIX = "t";


    // =================================================================================
    //  CONTEXT / CONFIGURATION SET UP
    // =================================================================================

    @Test
    public void setContextRejectsNullContext() {

        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();

        final IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> handler.setContext(null));

        assertEquals("Context cannot be null", exception.getMessage());

    }


    @Test
    public void setContextRejectsContextWithoutTemplateMode() {

        final Harness harness = new Harness(HTML, Collections.<IProcessor>emptyList());
        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();

        final ITemplateContext contextWithoutTemplateMode =
                (ITemplateContext) Proxy.newProxyInstance(
                        ProcessorTemplateHandlerTests.class.getClassLoader(),
                        new Class<?>[]{ITemplateContext.class},
                        new InvocationHandler() {
                            public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
                                if ("getTemplateMode".equals(method.getName())) {
                                    return null;
                                }
                                return invokeDelegate(harness.context, method, args);
                            }
                        });

        final IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> handler.setContext(contextWithoutTemplateMode));

        assertEquals("Template Mode returned by context cannot be null", exception.getMessage());

    }


    @Test
    public void processesTemplateWithContextThatIsNotAnEngineContext() {

        final Harness harness =
                new Harness(HTML, Collections.<IProcessor>singletonList(
                        textProcessor(100, new TextAction() {
                            public void execute(final ITemplateContext context, final IText text, final ITextStructureHandler structureHandler) {
                                structureHandler.setText("[" + text.getText() + "]");
                            }
                        })));

        // A context that is a ITemplateContext but NOT an IEngineContext: no local variable support
        final ITemplateContext nonEngineContext =
                (ITemplateContext) Proxy.newProxyInstance(
                        ProcessorTemplateHandlerTests.class.getClassLoader(),
                        new Class<?>[]{ITemplateContext.class},
                        new InvocationHandler() {
                            public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
                                return invokeDelegate(harness.context, method, args);
                            }
                        });

        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();
        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        handler.setContext(nonEngineContext);
        handler.setNext(next);

        process(handler, nonEngineContext, "<p>x</p>");

        assertEquals("<p>[x]</p>", next.output());
        // Context levels are not tracked at all when there is no IEngineContext behind the ITemplateContext
        assertEquals(0, harness.context.level());

    }


    @Test
    public void ignoresLocalVariablesSetByTemplateBoundariesProcessorsWhenContextIsNotAnEngineContext() {

        final Harness harness =
                new Harness(HTML, Arrays.<IProcessor>asList(
                        templateBoundariesProcessor(10,
                                new BoundariesAction() {
                                    public void execute(final ITemplateContext context, final ITemplateBoundariesStructureHandler structureHandler) {
                                        structureHandler.setLocalVariable("global", "G");
                                    }
                                },
                                NO_END_ACTION),
                        tagProcessor("read", 100, new ElementTagAction() {
                            public void execute(final ITemplateContext context, final IProcessableElementTag tag, final IElementTagStructureHandler structureHandler) {
                                structureHandler.setBody(String.valueOf(context.getVariable("global")), false);
                            }
                        })));

        final ITemplateContext nonEngineContext =
                (ITemplateContext) Proxy.newProxyInstance(
                        ProcessorTemplateHandlerTests.class.getClassLoader(),
                        new Class<?>[]{ITemplateContext.class},
                        new InvocationHandler() {
                            public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
                                return invokeDelegate(harness.context, method, args);
                            }
                        });

        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();
        final RecordingTemplateHandler next = new RecordingTemplateHandler();
        handler.setContext(nonEngineContext);
        handler.setNext(next);

        process(handler, nonEngineContext, "<p t:read=\"1\">x</p>");

        // Variable modifications cannot be applied (no engine context), but processing must not fail
        assertEquals("<p t:read=\"1\">null</p>", next.output());

    }


    // =================================================================================
    //  FAIL FAST: NO PROCESSORS ASSOCIATED TO THE STRUCTURE
    // =================================================================================

    @Test
    public void forwardsAllEventsUntouchedWhenThereAreNoProcessors() {

        final Harness harness = new Harness(HTML, Collections.<IProcessor>emptyList());

        harness.process("<!DOCTYPE html><div>hello<!-- note --><br/></div>");

        assertEquals("<!DOCTYPE html><div>hello<!-- note --><br/></div>", harness.next.output());

        final List<ITemplateEvent> events = harness.next.events;
        assertEquals(8, events.size());
        assertTrue(events.get(0) instanceof ITemplateStart);
        assertTrue(events.get(1) instanceof IDocType);
        assertTrue(events.get(2) instanceof IOpenElementTag);
        assertTrue(events.get(3) instanceof IText);
        assertTrue(events.get(4) instanceof IComment);
        assertTrue(events.get(5) instanceof IStandaloneElementTag);
        assertTrue(events.get(6) instanceof ICloseElementTag);
        assertTrue(events.get(7) instanceof ITemplateEnd);

    }


    @Test
    public void doesNotPerformTearDownChecksWhenThereAreNoTemplateBoundariesProcessors() {

        final Harness harness = new Harness(HTML, Collections.<IProcessor>emptyList());
        final IModelFactory modelFactory = harness.context.getModelFactory();

        harness.handler.handleTemplateStart(TemplateStart.TEMPLATE_START_INSTANCE);
        // An open element that is never closed: model level will stay at 1 at template end
        harness.handler.handleOpenElement(modelFactory.createOpenElementTag("div"));

        // No exception is raised: the handler "fails fast" on template end because there are no
        // template boundaries processors, and therefore no tear down checks are performed.
        harness.handler.handleTemplateEnd(TemplateEnd.TEMPLATE_END_INSTANCE);

        assertEquals(3, harness.next.events.size());
        assertTrue(harness.next.events.get(1) instanceof IOpenElementTag);
        assertTrue(harness.next.events.get(2) instanceof ITemplateEnd);

    }


