    @Test
    public void nonProcessableTextReplacementIsDelegatedToNextWithoutBeingReprocessed() {

        final List<String> processedTexts = new ArrayList<String>();

        final Harness harness = new Harness(HTML, Collections.<IProcessor>singletonList(
                textProcessor(100, new TextAction() {
                    public void execute(final ITemplateContext context, final IText text, final ITextStructureHandler structureHandler) {
                        processedTexts.add(text.getText());
                        if ("a".equals(text.getText())) {
                            final IModelFactory modelFactory = context.getModelFactory();
                            structureHandler.replaceWith(
                                    modelFactory.createModel(modelFactory.createText("b")), false);
                        }
                    }
                })));

        harness.process("<p>a</p>");

        assertEquals("<p>b</p>", harness.next.output());
        // The replacement was not processed again (it is executed by the next handler in the chain)
        assertEquals(Collections.singletonList("a"), processedTexts);

    }


    @Test
    public void processableTextReplacementIsProcessedAgainByTheHandler() {

        final List<String> processedTexts = new ArrayList<String>();

        final Harness harness = new Harness(HTML, Collections.<IProcessor>singletonList(
                textProcessor(100, new TextAction() {
                    public void execute(final ITemplateContext context, final IText text, final ITextStructureHandler structureHandler) {
                        processedTexts.add(text.getText());
                        if ("a".equals(text.getText())) {
                            final IModelFactory modelFactory = context.getModelFactory();
                            structureHandler.replaceWith(
                                    modelFactory.createModel(modelFactory.createText("b")), true);
                        } else {
                            structureHandler.setText(text.getText() + "!");
                        }
                    }
                })));

        harness.process("<p>a</p>");

        assertEquals("<p>b!</p>", harness.next.output());
        assertEquals(Arrays.asList("a", "b"), processedTexts);

    }


