    @Test
    public void allowsTemplateBoundariesProcessorsToInsertTextAtBothBoundaries() {

        final Harness harness = new Harness(HTML, Collections.<IProcessor>singletonList(
                templateBoundariesProcessor(100,
                        new BoundariesAction() {
                            public void execute(final ITemplateContext context, final ITemplateBoundariesStructureHandler structureHandler) {
                                structureHandler.insert("S", false);
                            }
                        },
                        new BoundariesAction() {
                            public void execute(final ITemplateContext context, final ITemplateBoundariesStructureHandler structureHandler) {
                                structureHandler.insert("E", false);
                            }
                        })));

        harness.process("<p>x</p>");

        assertEquals("S<p>x</p>E", harness.next.output());

        final List<ITemplateEvent> events = harness.next.events;
        assertTrue(events.get(0) instanceof ITemplateStart);
        assertTrue(events.get(1) instanceof IText);
        assertEquals("S", ((IText) events.get(1)).getText());
        // Inserted content at template end is executed BEFORE the template end event itself
        assertTrue(events.get(events.size() - 1) instanceof ITemplateEnd);
        assertEquals("E", ((IText) events.get(events.size() - 2)).getText());

    }


